11		"time"
12	)
13	
14	// 构造一份手工台账 JSON（按持久化结构序列化）。
15	func writeStateFile(t *testing.T, dir string, st *persistedState) []byte {
16		t.Helper()
17		if st.Requests == nil {
18			st.Requests = map[string]*requestRecord{}
19		}
20		data, err := json.MarshalIndent(st, "", "  ")
21		if err != nil {
22			t.Fatalf("序列化台账失败: %v", err)
23		}
24		if err := os.WriteFile(filepath.Join(dir, stateFileName), data, 0o644); err != nil {
25			t.Fatalf("写入台账文件失败: %v", err)
26		}
27		return data
28	}
29	
30	func recipeR1v1() *recipeRecord {
31		return &recipeRecord{RecipeNo: "R1", Version: "v1", Name: "配方一",
32			Materials: []materialRecord{{MaterialNo: "M1", GramsMilli: 100000}}}
33	}
34	
35	// Open 时只要有一个批次找不到绑定的配方版本就必须返回 ErrCorruptData：
36	// 草稿、执行中、已关闭三种状态都要保留自己绑定的配方依据；
37	// 错误信息需包含批次编号及其所需的配方编号、版本号；
38	// 不返回可用的台账对象，也不改写原文件。
39	func TestOpenRejectsBatchMissingRecipeVersion(t *testing.T) {
40		for _, status := range []BatchStatus{StatusDraft, StatusExecuting, StatusClosed} {
41			t.Run(string(status), func(t *testing.T) {
42				dir := t.TempDir()
43				original := writeStateFile(t, dir, &persistedState{
44					Version: stateVersion,
45					Recipes: []*recipeRecord{recipeR1v1()},
46					Batches: []*batchRecord{{
47						BatchNo:         "B-bad",
48						RecipeNo:        "R1",
49						RecipeVersion:   "v9", // 从未登记
50						PlannedPortions: 2,
51						Status:          status,
52					}},
53				})
54	
55				s, err := Open(dir)
56				if !errors.Is(err, ErrCorruptData) {
57					t.Fatalf("批次缺少配方版本应返回 ErrCorruptData，得到 %v", err)
58				}
59				if s != nil {
60					s.Close()
61					t.Fatalf("损坏台账不应返回可用的 Store 对象")
62				}
63				msg := err.Error()
64				for _, want := range []string{"B-bad", "R1", "v9"} {
65					if !strings.Contains(msg, want) {
66						t.Fatalf("错误信息应包含 %q，得到 %v", want, err)
67					}
68				}
69				// 原台账内容保留：Open 不得删除批次或把剩余记录另存为完整台账。
70				got, err := os.ReadFile(filepath.Join(dir, stateFileName))
71				if err != nil {
72					t.Fatal(err)
73				}
74				if !bytes.Equal(got, original) {
75					t.Fatalf("拒绝打开不应改动台账文件")
76				}
77			})
78		}
79	}
80	
81	// 配方编号相同而版本不同仍算缺失：存在 R1/v2 但批次绑定 R1/v1 时，
82	// 不能自动改用其他版本，Open 仍必须失败。
83	func TestOpenSameRecipeNoDifferentVersionStillMissing(t *testing.T) {
84		dir := t.TempDir()
85		r2 := recipeR1v1()
86		r2.Version = "v2"
87		writeStateFile(t, dir, &persistedState{
88			Version: stateVersion,
89			Recipes: []*recipeRecord{r2},
90			Batches: []*batchRecord{{
91				BatchNo: "B1", RecipeNo: "R1", RecipeVersion: "v1",
92				PlannedPortions: 1, Status: StatusDraft,
93			}},
94		})
95		if _, err := Open(dir); !errors.Is(err, ErrCorruptData) {
96			t.Fatalf("同编号的其他版本不能替代缺失版本，得到 %v", err)
97		}
98	}
99	
100	// 台账里其他批次完整也不能绕过：只要一个批次缺配方版本，Open 整体失败。
101	// 恢复缺失的原配方版本后重新打开，三个批次（含各自状态与份数）都继续可用。
102	func TestOpenOneBrokenBatchAmongCompleteOnes(t *testing.T) {
103		dir := t.TempDir()
104		writeStateFile(t, dir, &persistedState{
105			Version: stateVersion,
106			Recipes: []*recipeRecord{recipeR1v1()},
107			Batches: []*batchRecord{
108				{BatchNo: "B-ok-1", RecipeNo: "R1", RecipeVersion: "v1", PlannedPortions: 1, Status: StatusDraft},
109				{BatchNo: "B-bad", RecipeNo: "R1", RecipeVersion: "v9", PlannedPortions: 2, Status: StatusExecuting},
110				{BatchNo: "B-ok-2", RecipeNo: "R1", RecipeVersion: "v1", PlannedPortions: 3, Status: StatusClosed},
111			},
112		})
113		if _, err := Open(dir); !errors.Is(err, ErrCorruptData) {
114			t.Fatalf("存在完整批次也应整体拒绝，得到 %v", err)
115		}
116	
117		// 恢复 B-bad 所需的原配方版本 R1/v9（不是用其他版本顶替）。
118		r9 := recipeR1v1()
119		r9.Version = "v9"
120		writeStateFile(t, dir, &persistedState{
121			Version: stateVersion,
122			Recipes: []*recipeRecord{recipeR1v1(), r9},
123			Batches: []*batchRecord{
124				{BatchNo: "B-ok-1", RecipeNo: "R1", RecipeVersion: "v1", PlannedPortions: 1, Status: StatusDraft},
125				{BatchNo: "B-bad", RecipeNo: "R1", RecipeVersion: "v9", PlannedPortions: 2, Status: StatusExecuting},
126				{BatchNo: "B-ok-2", RecipeNo: "R1", RecipeVersion: "v1", PlannedPortions: 3, Status: StatusClosed},
127			},
128		})
129		s, err := Open(dir)
130		if err != nil {
131			t.Fatalf("恢复缺失版本后重新打开应成功: %v", err)
132		}
133		defer s.Close()
134		for _, want := range []struct {
135			no       string
136			version  string
137			portions int
138			status   BatchStatus
139		}{
140			{"B-ok-1", "v1", 1, StatusDraft},
141			{"B-bad", "v9", 2, StatusExecuting},
142			{"B-ok-2", "v1", 3, StatusClosed},
143		} {
144			b, err := s.GetBatch(want.no)
145			if err != nil {
146				t.Fatalf("恢复后查询批次 %q 失败: %v", want.no, err)
147			}
148			if b.RecipeVersion != want.version || b.PlannedPortions != want.portions || b.Status != want.status {
149				t.Fatalf("批次 %q 原有内容应保留，得到 %+v", want.no, b)
150			}
151		}
152	}
153	
154	// 已登记但暂时没有批次使用的配方版本可以保留；无批次台账正常打开。
155	func TestOpenKeepsRegisteredButUnusedRecipes(t *testing.T) {
156		dir := t.TempDir()
157		s1, err := Open(dir)
158		if err != nil {
159			t.Fatal(err)
160		}
161		if _, err := s1.RegisterRecipe("r1", "R1", "v1", "配方一", []MaterialInput{
162			{MaterialNo: "M1", Grams: "100"},
163		}); err != nil {
164			t.Fatal(err)
165		}
166		if err := s1.Close(); err != nil {
167			t.Fatal(err)
168		}
169		s2, err := Open(dir)
170		if err != nil {
171			t.Fatalf("只有配方、没有批次的台账应能正常打开: %v", err)
172		}
173		defer s2.Close()
174		r, err := s2.GetRecipe("R1", "v1")
175		if err != nil || r.Name != "配方一" {
176			t.Fatalf("未被批次使用的配方版本应保留，得到 %v %+v", err, r)
177		}
178	}
179	
180	// 台账打开后本地文件被改坏（缺少批次绑定的配方版本）：
181	// 下一次查询或写入都必须返回 ErrCorruptData，不得返回不完整视图、
182	// 不得继续使用此前读到的配方、不得崩溃；操作其他完整批次也不能绕过。
183	// 被拒绝的写入不留业务记录、不占用请求编号；恢复缺失版本后原记录继续可用。
184	func TestCorruptionAfterOpenDetectedOnNextAccess(t *testing.T) {
185		dir := t.TempDir()
186		s, err := Open(dir)
187		if err != nil {
188			t.Fatal(err)
189		}
190		defer s.Close()
191	
192		if _, err := s.RegisterRecipe("r1", "R1", "v1", "配方一", []MaterialInput{
193			{MaterialNo: "M1", Grams: "100"},
194		}); err != nil {
195			t.Fatal(err)
196		}
197		if _, err := s.RegisterRecipe("r2", "R2", "v1", "配方二", []MaterialInput{
198			{MaterialNo: "M1", Grams: "2"},
199		}); err != nil {
200			t.Fatal(err)
201		}
202		// B1：草稿绑定 R1/v1；B2：执行中绑定 R2/v1（完整批次）；B3：已关闭绑定 R1/v1。
203		if _, err := s.CreateBatch("b1", "B1", "R1", "v1", 10); err != nil {
204			t.Fatal(err)
205		}
206		if _, err := s.CreateBatch("b2", "B2", "R2", "v1", 10); err != nil {
207			t.Fatal(err)
208		}
209		if _, err := s.StartBatch("s2", "B2"); err != nil {
210			t.Fatal(err)
211		}
212		if _, err := s.CreateBatch("b3", "B3", "R1", "v1", 10); err != nil {
213			t.Fatal(err)
214		}
215		if _, err := s.StartBatch("s3", "B3"); err != nil {
216			t.Fatal(err)
217		}
218		fixedTime := time.Date(2026, 8, 1, 9, 0, 0, 0, time.UTC)
219		if _, err := s.AddFeeding("feed-b2", "B2", "M1", "5", fixedTime, "张三"); err != nil {
220			t.Fatal(err)
221		}
222		if _, err := s.CloseBatch("c3", "B3"); err != nil {
223			t.Fatal(err)
224		}
225	
226		// 保存完好时的文件内容，随后从文件中删掉 R1/v1（B1、B3 失去配方依据，B2 仍完整）。
227		good, err := os.ReadFile(filepath.Join(dir, stateFileName))
228		if err != nil {
229			t.Fatal(err)
230		}
231		var broken persistedState
232		if err := json.Unmarshal(good, &broken); err != nil {
233			t.Fatal(err)
234		}
235		kept := broken.Recipes[:0]
236		for _, r := range broken.Recipes {
237			if !(r.RecipeNo == "R1" && r.Version == "v1") {
238				kept = append(kept, r)
239			}
240		}
241		broken.Recipes = kept
242		badBytes := writeStateFile(t, dir, &broken)
243	
244		// 查询：损坏批次、完整批次、配方查询，全部失败；不得崩溃。
245		for _, batchNo := range []string{"B1", "B2", "B3"} {
246			if _, err := s.GetBatch(batchNo); !errors.Is(err, ErrCorruptData) {
247				t.Fatalf("文件损坏后查询批次 %q 应返回 ErrCorruptData，得到 %v", batchNo, err)
248			}
249		}
250		if _, err := s.GetRecipe("R2", "v1"); !errors.Is(err, ErrCorruptData) {
251			t.Fatalf("文件损坏后不能继续使用此前读到的配方，得到 %v", err)
252		}
253	
254		// 写入：对损坏批次与对完整批次的操作都必须被拒绝（不得崩溃、不得放行）。
